CREATE TABLE "app"."reviews" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "book_id" bigint NOT NULL,
  "body" text NOT NULL DEFAULT ''
)
ALTER TABLE "app"."reviews" ADD CONSTRAINT "reviews_pkey" PRIMARY KEY (id)
CREATE INDEX reviews_book_idx ON app.reviews USING btree (book_id)
ALTER TABLE "app"."reviews" ADD CONSTRAINT "reviews_book_fkey" FOREIGN KEY (book_id) REFERENCES app.books(id) ON DELETE CASCADE
